'use strict';
// The plugin consumes only the validated projection generated by the Go planner.
const fs = require('node:fs');
const path = require('node:path');
const { createNodesFromFiles, DependencyType } = require('@nx/devkit');

const createFeatureNodes = (file, options, context) => {
  const projection = JSON.parse(fs.readFileSync(path.join(context.workspaceRoot, file), 'utf8'));
  const projects = {};
  for (const feature of projection.features) {
    const inputs = feature.inputs.map((input) => `{workspaceRoot}/${input}`);
    projects[feature.root] = {
      name: feature.name,
      root: feature.root,
      projectType: 'library',
      namedInputs: { default: [...inputs] },
      targets: Object.fromEntries(feature.checks.map((check) => [check, { inputs: ['default'] }])),
    };
  }
  return { projects };
};
const createNodes = ['catalogue.json', async (files, options, context) =>
  createNodesFromFiles(createFeatureNodes, files, options, context)];
// Both supported public plugin entry points use the same projection.
exports.createNodes = createNodes;
exports.createNodesV2 = createNodes;
exports.createDependencies = (options, context) => {
  const projection = JSON.parse(fs.readFileSync(path.join(context.workspaceRoot, 'catalogue.json'), 'utf8'));
  const roots = Object.fromEntries(projection.features.map(f => [f.name, f.root]));
  return projection.edges.map(([source, target]) => ({
    source, target, type: DependencyType.static, sourceFile: `${roots[source]}/ci-unit.json`,
  }));
};

// Nx resolves its public CLI package relative to the isolated workspace.
// The only module tree exposed there is this reviewed tool installation.
if (require.main === module) {
  if (process.argv.length !== 4 || process.argv[2] !== '--prepare-workspace') {
    throw new Error('invalid workspace preparation');
  }
  const workspace = fs.realpathSync(process.argv[3]);
  if (!path.isAbsolute(process.argv[3]) || !fs.statSync(workspace).isDirectory()) {
    throw new Error('invalid workspace preparation');
  }
  const modules = path.join(fs.realpathSync(__dirname), 'node_modules');
  const destination = path.join(workspace, 'node_modules');
  fs.symlinkSync(modules, destination, process.platform === 'win32' ? 'junction' : 'dir');
}
